"use client"

import { useState, useEffect } from "react"
import { useApp } from "@/components/providers/app-provider"
import Header from "@/components/Header"
import TabNavigation from "@/components/TabNavigation"
import TasksView from "@/components/TasksView"
import ProgressView from "@/components/ProgressView"
import AdminDashboard from "@/components/AdminDashboard"
import ProfileModal from "@/components/ProfileModal"
import BottomNavigation from "@/components/BottomNavigation"

export default function Home() {
  const { user, connectWallet } = useApp()
  const [activeTab, setActiveTab] = useState<"tasks" | "progress">("tasks")
  const [showProfile, setShowProfile] = useState(false)
  const [selectedCategory, setSelectedCategory] = useState("ALL")
  const [selectedFilter, setSelectedFilter] = useState("ALL")

  // Auto-connect as admin on load
  useEffect(() => {
    if (!user) {
      connectWallet("admin")
    }
  }, [user, connectWallet])

  if (!user) {
    return (
      <div className="min-h-screen bg-gray-900 flex justify-center">
        <div className="w-full max-w-md bg-cream relative border-l-4 border-r-4 border-black min-h-screen flex items-center justify-center">
          <div className="pixel-card text-center">
            <h1 className="pixel-font text-lg mb-4">👑 ADMIN LOGIN</h1>
            <p className="pixel-font text-xs mb-4">Connecting as System Administrator...</p>
            <div className="pixel-border bg-purple-200 p-3">
              <span className="pixel-font text-xs">Loading Admin Panel...</span>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-900 flex justify-center">
      <div className="w-full max-w-md bg-cream relative border-l-4 border-r-4 border-black min-h-screen">
        <Header onProfileClick={() => setShowProfile(true)} />

        <div className="pb-20">
          <TabNavigation activeTab={activeTab} onTabChange={setActiveTab} />

          {user.role === "admin" ? (
            <AdminDashboard />
          ) : activeTab === "tasks" ? (
            <TasksView
              selectedCategory={selectedCategory}
              selectedFilter={selectedFilter}
              onCategoryChange={setSelectedCategory}
              onFilterChange={setSelectedFilter}
            />
          ) : (
            <ProgressView />
          )}
        </div>

        <BottomNavigation
          activeTab={user.role === "admin" ? "admin" : activeTab === "tasks" ? "tasks" : "progress"}
          onTabChange={(tab) => {
            if (tab === "profile") {
              setShowProfile(true)
            } else if (user.role !== "admin") {
              setActiveTab(tab as "tasks" | "progress")
            }
          }}
        />

        {showProfile && <ProfileModal onClose={() => setShowProfile(false)} />}
      </div>
    </div>
  )
}

