@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --yellow-soft: #fff3b0;
    --pink-soft: #f4c2c2;
    --green-soft: #90c695;
    --green-bright: #4ade80;
    --orange: #fb923c;
    --black: #000000;
    --cream: #f5f5dc;
  }
}

@layer components {
  .pixel-font {
    font-family: "Courier New", "Monaco", "Menlo", "Consolas", monospace;
    font-weight: bold;
    letter-spacing: 0.5px;
  }

  .pixel-border {
    border: 3px solid #000000;
    box-shadow: 3px 3px 0px #000000;
  }

  .pixel-button {
    @apply pixel-border pixel-font text-xs p-2 cursor-pointer select-none transition-all;
    min-height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .pixel-card {
    @apply pixel-border bg-white p-3;
  }

  .pixel-input {
    @apply pixel-border p-2 bg-white text-black pixel-font text-sm;
  }

  .pixel-tab {
    @apply pixel-font text-sm p-3 cursor-pointer select-none;
    border: 3px solid #000000;
    min-height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .pixel-tab.active {
    @apply bg-pink-soft;
  }

  .pixel-tab.inactive {
    @apply bg-white;
  }
}

body {
  background-color: var(--cream);
  margin: 0;
  padding: 0;
  min-height: 100vh;
  -webkit-text-size-adjust: 100%;
  -webkit-tap-highlight-color: transparent;
}

/* Mobile optimizations */
@media (max-width: 768px) {
  .pixel-font {
    letter-spacing: 0.3px;
  }

  .pixel-border {
    border: 2px solid #000000;
    box-shadow: 2px 2px 0px #000000;
  }
}

