"use client"

import { createContext, useContext, useState, type ReactNode } from "react"

interface User {
  address: string
  role: "admin" | "partner" | "contributor"
  name: string
  avatar: string
  totalEarned?: number
  tasksCompleted?: number
  tasksCreated?: number
  rewardsDistributed?: number
  usersManaged?: number
  totalPlatformValue?: number
}

interface Task {
  id: string
  title: string
  category: "Education" | "Research" | "Event" | "Partner Task" | "Other"
  reward: number
  complexity: "Low" | "Medium" | "High"
  validationType: "Manual" | "File Upload" | "Auto" | "URL Submission"
  instructions: string
  slots: number
  deadline?: string
  status: "Active" | "Pending" | "Completed" | "Claimed"
  createdBy: string
  claimedBy?: string
  submittedProof?: string
}

interface AppContextType {
  user: User | null
  tasks: Task[]
  connectWallet: (walletType: string) => void
  createTask: (task: Omit<Task, "id" | "createdBy" | "status">) => void
  claimTask: (taskId: string) => void
  submitTask: (taskId: string, proof: string) => void
  approveTask: (taskId: string) => void
  deleteTask: (taskId: string) => void
  banUser: (userAddress: string) => void
}

const AppContext = createContext<AppContextType | undefined>(undefined)

const mockTasks: Task[] = [
  {
    id: "1",
    title: "Complete Celo DeFi Tutorial",
    category: "Education",
    reward: 5,
    complexity: "Low",
    validationType: "URL Submission",
    instructions: "Complete the Celo DeFi tutorial and submit the completion certificate URL",
    slots: 10,
    status: "Active",
    createdBy: "0x1234...partner",
  },
  {
    id: "2",
    title: "Research Web3 Impact Projects",
    category: "Research",
    reward: 15,
    complexity: "Medium",
    validationType: "File Upload",
    instructions: "Research and document 5 Web3 projects making social impact. Submit a 2-page report.",
    slots: 5,
    status: "Active",
    createdBy: "0x1234...partner",
  },
  {
    id: "3",
    title: "Create Social Media Content",
    category: "Partner Task",
    reward: 50,
    complexity: "Medium",
    validationType: "Manual",
    instructions: "Design 3 Instagram posts about sustainable farming in Chapada region",
    slots: 2,
    status: "Pending",
    createdBy: "0x1234...partner",
    claimedBy: "0x5678...contributor",
    submittedProof: "Instagram posts created and uploaded",
  },
]

export function AppProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [tasks, setTasks] = useState<Task[]>(mockTasks)

  const connectWallet = (walletType: string) => {
    // Mock admin user connection
    const mockUser: User = {
      address: "0xADMIN1234567890",
      role: "admin",
      name: "System Administrator",
      avatar: "👑",
      usersManaged: 156,
      totalPlatformValue: 2450,
      tasksCreated: 25,
      rewardsDistributed: 1200,
    }
    setUser(mockUser)
  }

  const createTask = (taskData: Omit<Task, "id" | "createdBy" | "status">) => {
    const newTask: Task = {
      ...taskData,
      id: Date.now().toString(),
      createdBy: user?.address || "",
      status: "Active",
    }
    setTasks((prev) => [...prev, newTask])
  }

  const claimTask = (taskId: string) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === taskId ? { ...task, status: "Claimed" as const, claimedBy: user?.address } : task,
      ),
    )
  }

  const submitTask = (taskId: string, proof: string) => {
    setTasks((prev) =>
      prev.map((task) => (task.id === taskId ? { ...task, status: "Pending" as const, submittedProof: proof } : task)),
    )
  }

  const approveTask = (taskId: string) => {
    setTasks((prev) => prev.map((task) => (task.id === taskId ? { ...task, status: "Completed" as const } : task)))
  }

  const deleteTask = (taskId: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== taskId))
  }

  const banUser = (userAddress: string) => {
    // Mock ban user functionality
    console.log(`User ${userAddress} has been banned by admin`)
  }

  return (
    <AppContext.Provider
      value={{
        user,
        tasks,
        connectWallet,
        createTask,
        claimTask,
        submitTask,
        approveTask,
        deleteTask,
        banUser,
      }}
    >
      {children}
    </AppContext.Provider>
  )
}

export const useApp = () => {
  const context = useContext(AppContext)
  if (context === undefined) {
    throw new Error("useApp must be used within an AppProvider")
  }
  return context
}
